<?php
require_once __DIR__.'/includes/auth.php';require_login();$pdo=db();$id=(int)($_GET['id']??0);$download=isset($_GET['download']);$inline=isset($_GET['inline']);
$stmt=$pdo->prepare('SELECT a.*,d.resident_id AS document_resident,b.resident_id AS blotter_resident FROM attachments a LEFT JOIN document_requests d ON a.entity=\'document_request\' AND d.id=a.entity_id LEFT JOIN blotters b ON a.entity=\'blotter\' AND b.id=a.entity_id WHERE a.id=?');$stmt->execute([$id]);$file=$stmt->fetch();if(!$file){http_response_code(404);exit('Evidence file not found.');}
$user=current_user();$allowed=$user['role']!=='resident';if($user['role']==='resident')$allowed=(int)($file['document_resident']??0)===(int)($user['resident_id']??0)||(int)($file['blotter_resident']??0)===(int)($user['resident_id']??0);if(!$allowed){http_response_code(403);exit('You do not have permission to access this evidence.');}
$root=realpath(__DIR__.'/assets/attachments');$path=realpath(__DIR__.'/'.ltrim($file['stored_path'],'/'));if(!$root||!$path||strncmp($path,$root,strlen($root))!==0||!is_file($path)){http_response_code(404);exit('Stored evidence is unavailable.');}$mime=preg_replace('/[^a-zA-Z0-9.+-\/]/','',$file['mime_type'])?:'application/octet-stream';$filename=str_replace(["\r","\n",'"'],'_',basename($file['original_name']));
if($download||$inline){if($download)audit_action('attachment_downloaded','attachments',$id,$file['original_name']);else audit_action('attachment_viewed','attachments',$id,$file['original_name']);header('X-Content-Type-Options: nosniff');header('Content-Type: '.$mime);header('Content-Length: '.filesize($path));header('Content-Disposition: '.($download?'attachment':'inline').'; filename="'.$filename.'"');readfile($path);exit;}
audit_action('attachment_viewed','attachments',$id,$file['original_name']);$pageTitle='Evidence file';$activePage='documents';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Protected evidence / <?= h(ucwords(str_replace('_',' ',$file['entity']))) ?></div><h1><?= h($file['original_name']) ?></h1><p>Access is restricted to the submitting resident and authorized staff. Every view and download is recorded in the audit log.</p></div><div class="request-actions"><a class="secondary-button" href="attachment.php?id=<?= h($id) ?>&download=1">Download evidence</a><a class="text-button" href="<?= $file['entity']==='blotter'?'blotters.php':'documents.php' ?>">Back to records</a></div></section><section class="content-two-col"><section class="panel form-panel"><div class="eyebrow">File preview</div><?php if(str_starts_with($mime,'image/')): ?><img src="attachment.php?id=<?= h($id) ?>&inline=1" alt="<?= h($file['original_name']) ?>" style="max-width:100%;max-height:620px;object-fit:contain"><?php elseif($mime==='application/pdf'): ?><iframe src="attachment.php?id=<?= h($id) ?>&inline=1" title="Evidence PDF" style="width:100%;height:620px;border:1px solid #dbe3eb"></iframe><?php else: ?><p class="empty-state">This file type can be downloaded but not previewed in the browser.</p><?php endif; ?></section><aside class="panel detail-panel"><div class="eyebrow">File details</div><div class="detail-grid"><div><small>Original filename</small><strong><?= h($file['original_name']) ?></strong></div><div><small>Uploaded</small><strong><?= h(date('M d, Y h:i A',strtotime($file['created_at']))) ?></strong></div><div><small>File type</small><strong><?= h($mime) ?></strong></div><div><small>File size</small><strong><?= h(number_format((int)$file['file_size']/1024,1)) ?> KB</strong></div><div><small>Record</small><strong><?= h(ucwords(str_replace('_',' ',$file['entity']))) ?> #<?= h($file['entity_id']) ?></strong></div></div></aside></section><?php require __DIR__.'/partials/footer.php'; ?>
